// หาสมาชิกที่ "วันนี้ = วันเปลี่ยนตู้ - 5 วัน" (T-5) ตามเวลาไทย
// Asia/Bangkok = UTC+7 ตลอดปี (ไทยไม่มี DST) เลยเลื่อนเวลาแบบบวก 7 ชม. ได้ตรง ๆ
const bkk = new Date(Date.now() + 7 * 3600 * 1000);
const todayDOM = bkk.getUTCDate();
// จำนวนวันของ "เดือนนี้" — ใช้ตอนวันทักตกไปปลายเดือน (เช่น day=3 → ทักวันที่ 29-31 ของเดือนนี้)
const daysInThisMonth = new Date(Date.UTC(bkk.getUTCFullYear(), bkk.getUTCMonth() + 1, 0)).getUTCDate();

const out = [];
for (const item of $input.all()) {
  const line_uid = item.json.line_uid;
  const day = Number(item.json.day);           // 1–28 (บังคับที่ DB แล้ว)
  if (!line_uid || !day) continue;
  let ping = day - 5;
  if (ping < 1) ping += daysInThisMonth;       // day-5 < 1 → วนไปปลายเดือนปัจจุบัน (วันเปลี่ยนตู้อยู่เดือนหน้า)
  if (ping === todayDOM) out.push({ json: { line_uid, day } });
}
return out; // ว่าง = วันนี้ไม่มีใครถึงรอบ → node ถัดไปไม่ทำงาน

function bubble(title, body, btnLabel, uri, extra) {
  const bodyContents = [
    { type: 'text', text: title, weight: 'bold', size: 'md', wrap: true, color: '#1F2A22' },
    { type: 'text', text: body, size: 'sm', color: '#6B7A6E', wrap: true }
  ];
  if (extra) bodyContents.push({ type: 'text', text: extra, size: 'xs', color: '#8A9388', wrap: true, margin: 'md' });
  return {
    type: 'bubble',
    header: { type: 'box', layout: 'vertical', backgroundColor: '#3E5C46', paddingAll: '16px',
      contents: [ { type: 'text', text: 'LLOOP', color: '#FFFFFF', weight: 'bold', size: 'sm' } ] },
    body: { type: 'box', layout: 'vertical', spacing: 'sm', paddingAll: '20px', contents: bodyContents },
    footer: { type: 'box', layout: 'vertical', paddingAll: '16px',
      contents: [ { type: 'button', style: 'primary', color: '#3E5C46', height: 'sm',
        action: { type: 'uri', label: btnLabel, uri: uri } } ] }
  };
}

// สร้างข้อความ LINE ต่อสมาชิก 1 คน — uid/day ดึงจาก node กรองสมาชิก (n8n จับคู่ item ให้อัตโนมัติ)
const member = $('กรองสมาชิกที่วันนี้คือ T-5').item.json;
const title = 'กล่องเดือนนี้จัดให้แล้วค่ะ 💚';
const bodyText = 'แตะดูได้เลยนะคะ สลับชิ้นที่ไม่ถูกใจได้ถึงพรุ่งนี้ค่ะ (วันเปลี่ยนตู้ของคุณคือวันที่ ' + member.day + ')';
const contents = bubble(title, bodyText, 'เปิดดูกล่องของฉัน',
                        'https://wearlloop-dotcom.github.io/closet-day.html');
return { json: { lineBody: { to: member.line_uid, messages: [{ type: 'flex',
  altText: 'กล่องเดือนนี้จัดให้แล้วค่ะ — แตะดู สลับได้ถึงพรุ่งนี้', contents }] } } };
